2131	export class DuckDbOp extends Operator<DuckDbOp> {
2132	  static displayName = 'DuckDB'
2133	  static description = 'Query a DuckDB database using sql'
2134	  asDownload = () => this.outputData
2135	  createInputs() {
2136	    return {
2137	      query: new CodeField('SELECT 1 as val;', { language: 'sql' }),
2138	    }
2139	  }
2140	  createOutputs() {
2141	    return {
2142	      data: new DataField(),
2143	    }
2144	  }
2145	
2146	  async execute({
2147	    query: queryString = '',
2148	  }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> | null {
2149	    const queries = queryString
2150	      .split(';')
2151	      .map(s => s.trim())
2152	      .filter(Boolean)
2153	      .map(s => `${s};`)
2154	    if (!queries?.length) {
2155	      return { data: [] }
2156	    }
2157	
2158	    const db = await duckDbInstance
2159	    const conn = await db.connect()
2160	
2161	    try {
2162	      let data = []
2163	      for (const query of queries) {
2164	        if (!mustacheRe.test(query)) {
2165	          const result = await conn.query(query)
2166	          data = result.toArray()
2167	          continue
2168	        }
2169	
2170	        // Parse the query and extract references
2171	        const references: FieldReference[] = []
2172	        const parameterizedQuery = query.replace(mustacheRe, (raw, opId, inOut, fieldPath) => {
2173	          // If the opId is a relative path (doesn't start with /), make it relative to current context
2174	          const resolvedOpId = opId.startsWith('/') ? opId : `./${opId}`
2175	          references.push({ opId: resolvedOpId, inOut, fieldPath, raw })
2176	          return `$${references.length}` // $1, $2, etc.
2177	        })
2178	
2179	        // Resolve reference values
2180	        const positionalParams = references.map(({ opId, inOut, fieldPath }) => {
2181	          const op = getOp(opId, this.id)
2182	          const [firstKey, ...rest] = fieldPath.split('.')
2183	
2184	          const field = op?.[inOut === 'par' ? 'inputs' : 'outputs']?.[firstKey]
2185	          if (!field) {
2186	            throw new Error(`Field ${firstKey} not found on ${opId}`)
2187	          }
2188	
2189	          return rest.reduce((d, prop) => d[prop], field.value)
2190	        })
2191	
2192	        // Prepare the query with the current connection
2193	        const prepared = await conn.prepare(parameterizedQuery)
2194	
2195	        const result = await prepared.query(...positionalParams)
2196	        data = result.toArray()
2197	      }
2198	      await conn.close()
2199	      return { data }
2200	    } catch (e) {
2201	      debugExecute('Error executing query', e)
2202	      await conn.close()
2203	      await db.reset()
2204	      if (e instanceof Error) {
2205	        throw e
2206	      }
2207	      return null
2208	    }
2209	  }
2210	}
2211	
2212	export class JSONOp extends Operator<JSONOp> {
2213	  static displayName = 'JSON'
2214	  static description = 'Parse a JSON string'
2215	  createInputs() {
2216	    return {
2217	      text: new CodeField('{}', { language: 'json' }),
2218	    }
2219	  }
2220	  createOutputs() {
2221	    return {
2222	      data: new DataField(),
2223	    }
2224	  }
2225	  execute({ text }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
2226	    const json = text.replace(mustacheRe, (_, opId: string, inOut: InOut, fieldPath: string) => {
2227	      // If the opId is a relative path (doesn't start with /), make it relative to current context
2228	      const resolvedOpId = opId.startsWith('/') ? opId : `./${opId}`
2229	      const op = getOp(resolvedOpId, this.id)
2230	      const [fieldName, ...propKeys] = fieldPath.split('.')
2231	
2232	      const field = op?.[inOut === 'par' ? 'inputs' : 'outputs']?.[fieldName]
2233	      if (!field) {
2234	        throw new Error(`Field ${fieldName} not found on ${resolvedOpId}`)
2235	      }
2236	
2237	      const val = propKeys.reduce((d, prop) => d[prop], field.value)
2238	      return JSON.stringify(val)
2239	    })
2240	
2241	    const data = JSON.parse(json)
2242	    return { data }
2243	  }
2244	}
2245	
2246	export class ViewerOp extends Operator<ViewerOp> {
2247	  static displayName = 'Viewer'
2248	  static description = 'Inspect data in the viewer'
2249	  asDownload = () => this.inputs.data.value
2250	  createInputs() {
2251	    return {
2252	      data: new UnknownField(),
2253	    }
2254	  }
2255	
2256	  createOutputs() {
2257	    return {}
2258	  }
2259	
2260	  execute({ data }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
2261	    // This is a special-case because it's essentially a pass-through. The Viewer component will handle the data
2262	    return { data }
2263	  }
2264	}
2265	
2266	export class TableEditorOp extends Operator<TableEditorOp> {
2267	  static displayName = 'TableEditor'
2268	  static description = 'Edit a table with typed columns'
2269	  asDownload = () => this.outputData
2270	
2271	  createInputs() {
2272	    return {
2273	      data: new DataField(),
2274	      schema: new UnknownField(null), // TableSchema | null - optional schema override
2275	    }
2276	  }
2277	
2278	  createOutputs() {
2279	    return {
2280	      data: new DataField(),
2281	      schema: new UnknownField(null), // Computed schema (inferred or explicit)
2282	    }
2283	  }
2284	
2285	  execute({ data, schema }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
2286	    // Convert dateTime strings to Temporal.ZonedDateTime for output
2287	    // This happens at the operator boundary: internal storage = strings, output = Temporal
2288	    const outputData = schema ? prepareTableDataForOutput(data, schema as TableSchema) : data
2289	
2290	    return {
2291	      data: outputData,
2292	      schema: schema || null,
2293	    }
2294	  }
2295	}
2296	
2297	export class ChartOp extends Operator<ChartOp> {
2298	  static displayName = 'Chart'
2299	  static description = 'Create charts using Observable Plot (bar, histogram, scatter)'
2300	
2301	  createInputs() {
2302	    const data = new DataField()
2303	    const chartType = new StringLiteralField('bar', { values: ['bar', 'histogram', 'scatter'] })
2304	    const xField = new StringLiteralField('', [])
