import * as duckdb from '@duckdb/duckdb-wasm'
import { expect, test } from 'vitest'
// Grab the served URL for the example CSV the same way storage.ts does
import csvUrl from '../examples/quake-hexbins/data.csv?url'

async function makeDb() {
  const bundles = duckdb.getJsDelivrBundles()
  const bundle = await duckdb.selectBundle(bundles)
  const worker = new Worker(bundle.mainWorker!)
  const logger = new duckdb.ConsoleLogger(duckdb.LogLevel.WARNING)
  const db = new duckdb.AsyncDuckDB(logger, worker)
  await db.instantiate(bundle.mainModule, bundle.pthreadWorker)
  return db
}

test('h3 extension + read_csv over http', async () => {
  const db = await makeDb()
  const conn = await db.connect()
  await conn.query(`SET autoinstall_known_extensions = 1;`)
  // Try to load the community h3 extension
  let h3ok = false
  let h3err = ''
  try {
    await conn.query(`INSTALL h3 FROM community; LOAD h3;`)
    h3ok = true
  } catch (e) {
    h3err = String(e)
  }
  console.log('CSV URL:', csvUrl)
  console.log('H3 loaded:', h3ok, h3err)

  await conn.query(`INSTALL httpfs; LOAD httpfs;`)
  const fullUrl = new URL(csvUrl, window.location.origin).href
  console.log('Full CSV URL:', fullUrl)

  let readOk = false
  let readErr = ''
  try {
    const r = await conn.query(`SELECT count(*) as n FROM read_csv_auto('${fullUrl}')`)
    console.log('CSV count:', JSON.stringify(r.toArray().map(x => x.toJSON())))
    readOk = true
  } catch (e) {
    readErr = String(e)
    console.log('read_csv err:', readErr)
  }

  if (h3ok) {
    const r = await conn.query(
      `SELECT h3_latlng_to_cell(37.42417, -121.80650, 5) AS cell`
    )
    const cell = r.toArray()[0].toJSON()
    console.log('h3 cell:', JSON.stringify(cell))
  }

  await conn.close()
  expect(h3ok || h3err, 'probe ran').toBeTruthy()
})

